{
  "risk_tier": "High",
  "confidence": 0.85,
  "rationale": "Screens job applicants, which falls under employment and worker management.",
  "eu_ai_act_reference": "Annex III, point 4 (employment)",
  "nist_trustworthiness": [
    {
      "characteristic": "Fair with harmful bias managed",
      "concern": "High",
      "note": "Historic hiring data may encode bias"
    },
    {
      "characteristic": "Privacy-enhanced",
      "concern": "Medium",
      "note": "Processes personal data from CVs"
    }
  ],
  "nist_actions": {
    "govern": "Assign an accountable owner for the screening model",
    "map": "Document intended use, affected candidates and failure modes",
    "measure": "Test selection rates across protected groups before launch",
    "manage": "Human review of every automated rejection"
  },
  "iso42001_controls": [
    "A.5 - complete an AI system impact assessment covering candidates",
    "A.7 - document provenance and quality of training data",
    "A.10 - obtain vendor evidence of bias testing"
  ],
  "impact_assessment_required": true,
  "overall_risk_rating": "High",
  "key_risks": [
    "Discriminatory outcomes",
    "Lack of transparency to candidates"
  ],
  "injection_suspected": false
}

parameters.jsCode:
// Combine the request with the three-framework assessment into one case record.
// Code, not the model, decides the route. Review routes are logged as pending and
// handed to the review workflow, so the caller gets an answer immediately.
const req = $('Settings').first().json;
const a = $input.first().json.output || {};

const tiers = ['Prohibited', 'High', 'Limited', 'Minimal'];
const tier = tiers.includes(a.risk_tier) ? a.risk_tier : 'Unknown';
const overall = ['Low', 'Medium', 'High'].includes(a.overall_risk_rating) ? a.overall_risk_rating : 'Unknown';
const confidence = Number(a.confidence ?? 0);
const CONFIDENCE_THRESHOLD = Number($('Settings').first().json.confidence_threshold) || 0.7;

const nist = Array.isArray(a.nist_trustworthiness) ? a.nist_trustworthiness : [];
const highConcerns = nist.filter(c => c.concern === 'High').map(c => c.characteristic);
const actions = a.nist_actions || {};
const list = (x) => Array.isArray(x) ? x.join('; ') : (x || '');
const ia = a.impact_assessment_required === true;

let route, escalation_reason = '', decision, decided_by, next_step;
if (a.injection_suspected === true) {
  route = 'Needs triage';
  escalation_reason = 'Possible attempt to influence the AI assessment';
} else if (tier === 'Unknown' || overall === 'Unknown' || confidence < CONFIDENCE_THRESHOLD) {
  route = 'Needs triage';
  escalation_reason = 'Low confidence or incomplete assessment';
} else if (tier === 'Prohibited') {
  route = 'Prohibited';
} else if (tier === 'High') {
  route = 'Review';
  escalation_reason = 'EU AI Act high-risk';
} else if (overall === 'High' || highConcerns.length > 0) {
  route = 'Review';
  escalation_reason = 'NIST AI RMF high concern: ' + (highConcerns.join(', ') || 'overall rating High');
} else {
  route = 'Low';
}

if (route === 'Prohibited') {
  decision = 'Rejected - prohibited practice under EU AI Act Article 5';
  decided_by = 'Automated policy rule';
  next_step = 'Do not proceed. This use case matches a practice prohibited under Article 5 of the EU AI Act.';
} else if (route === 'Low') {
  decision = (tier === 'Limited' ? 'Auto-approved - transparency obligations apply' : 'Auto-approved - minimal risk')
    + (ia ? '; ISO 42001 impact assessment required before go-live' : '');
  decided_by = 'Automated policy rule';
  next_step = 'Approved. Apply the listed controls' + (ia ? ' and complete an AI system impact assessment' : '') + ' before go-live.';
} else if (route === 'Review') {
  decision = 'Pending human review';
  decided_by = 'Pending - governance reviewer';
  next_step = 'Sent to the governance reviewer. Do not start using this tool until it is approved. The requester will be emailed the decision.';
} else {
  decision = 'Pending triage';
  decided_by = 'Pending - governance team';
  next_step = 'Could not be classified with confidence and has been sent to the governance team for manual triage. Expect follow-up questions.';
}

return [{
  json: {
    case_id: 'AIU-' + Date.now().toString(36).toUpperCase(),
    submitted_at: new Date().toISOString(),
    requester: req.requester_name,
    email: req.requester_email,
    department: req.department,
    use_case: req.use_case_title,
    description: req.description,
    vendor: req.vendor,
    data_involved: req.data_involved,
    affected: req.affected,
    human_review: req.human_review,
    risk_tier: tier,
    overall_risk_rating: overall,
    confidence,
    rationale: a.rationale || '',
    eu_ai_act_reference: a.eu_ai_act_reference || '',
    nist_ratings: nist.map(c => `${c.characteristic}: ${c.concern} (${c.note || ''})`).join('; '),
    nist_high_concerns: highConcerns.join('; '),
    nist_govern: actions.govern || '',
    nist_map: actions.map || '',
    nist_measure: actions.measure || '',
    nist_manage: actions.manage || '',
    iso42001_controls: list(a.iso42001_controls),
    impact_assessment_required: ia ? 'Yes' : 'No',
    key_risks: list(a.key_risks),
    route,
    escalation_reason,
    final_risk_tier: '',
    reviewer_notes: '',
    decision,
    decided_by,
    decided_at: route === 'Review' || route === 'Needs triage' ? '' : new Date().toISOString(),
    next_step
  }
}];

// Pass the full case record, plus the settings the review workflow needs.
const s = $('Settings').first().json;
return [{ json: { ...$('Build case record').first().json,
  settings: { reviewer_email: s.reviewer_email, register_spreadsheet_url: s.register_spreadsheet_url, register_sheet_name: s.register_sheet_name } } }];

// The answer returned to the caller (the form workflow or the MCP tool / AI assistant).
const r = $('Build case record').first().json;
return [{
  json: {
    case_id: r.case_id,
    use_case: r.use_case,
    eu_ai_act_tier: r.risk_tier,
    eu_ai_act_reference: r.eu_ai_act_reference,
    overall_risk_rating: r.overall_risk_rating,
    confidence: r.confidence,
    route: r.route,
    decision: r.decision,
    next_step: r.next_step,
    rationale: r.rationale,
    nist_high_concerns: r.nist_high_concerns,
    required_controls: r.iso42001_controls,
    impact_assessment_required: r.impact_assessment_required,
    key_risks: r.key_risks
  }
}];

