parameters.jsCode:
// Merge the reviewer's approve/reject into the case record.
const { settings, ...rec } = $('Unpack case for review').first().json;
const approved = $input.first().json.data?.approved === true;
return [{ json: { ...rec,
  decision: approved ? 'Approved by reviewer - required controls apply' : 'Rejected by reviewer',
  decided_by: 'Human reviewer',
  decided_at: new Date().toISOString() } }];

// Merge the reviewer's triage classification and decision into the case record.
const { settings, ...rec } = $('Unpack case for review').first().json;
const r = $input.first().json.data || {};
const map = {
  'Approve': 'Approved after triage',
  'Approve with conditions': 'Approved after triage - conditions apply',
  'Reject': 'Rejected after triage',
  'Request more information': 'On hold - more information requested from requester'
};
return [{ json: { ...rec,
  final_risk_tier: r['Risk tier'] || '',
  reviewer_notes: r['Reviewer notes'] || '',
  decision: map[r['Decision']] || 'Triage response not recognised',
  decided_by: 'Human reviewer (triage)',
  decided_at: new Date().toISOString() } }];

